common_mistake.wrong:
let data = String::from("x");
let r1 = &mut data;
let r2 = &mut data; // ERROR!

common_mistake.right:
let mut data = String::from("x");
{
  let r1 = &mut data;
  r1.push_str("!");
} // r1 scope ends
let r2 = &mut data; // OK now

