c_sharp_class_to_rust_struct.rust:
pub struct Token {
  pub TokenType: TokenType,
  pub Line: usize,
}

impl Token {
  pub fn New(token_type: TokenType, line: usize) -> Self {
    Self { TokenType: token_type, Line: line }
  }
}
